INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist DVI ausschließlich für digitale Signale gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch analoge Unterstützung"}, {"text": "Ja", "correct": false, "because": "DVI-A und DVI-I"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hauptfunktion hat DVI?', 3, '[{"text": "Videosignale übertragen", "correct": true, "because": "Monitoranbindung"}, {"text": "Audiodaten senden", "correct": false, "because": "Kein Audio"}, {"text": "Netzwerkverbindung", "correct": false, "because": "Keine Netzwerkfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Varianten hat DVI?', 5, '[{"text": "DVI-D", "correct": true, "because": "Nur digital"}, {"text": "DVI-A", "correct": true, "because": "Nur analog"}, {"text": "DVI-H", "correct": false, "because": "Keine Variante"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DVI unterstützt digitale Signale. b) Es überträgt Audio.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kein Audio"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von DVI?', 4, '[{"text": "Kabeltyp", "correct": false, "because": "DVI-D, -A, -I unterschiedlich"}, {"text": "Auflösung", "correct": false, "because": "Beeinflusst Qualität"}, {"text": "Kabelgewicht", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DVI Audio unterstützt?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Video"}, {"text": "Ja", "correct": false, "because": "Kein Audiokanal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche DVI-Variante überträgt nur digitale Signale?', 3, '[{"text": "DVI-D", "correct": true, "because": "Digital only"}, {"text": "DVI-I", "correct": false, "because": "Digital und analog"}, {"text": "DVI-A", "correct": false, "because": "Nur analog"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet DVI?', 5, '[{"text": "Hohe Bildqualität", "correct": true, "because": "Digitale Übertragung"}, {"text": "Analoge Kompatibilität", "correct": true, "because": "DVI-I und DVI-A"}, {"text": "Audiounterstützung", "correct": false, "because": "Kein Audio"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DVI kann 4K übertragen. b) Es ist neuer als HDMI. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "HDMI ist neuer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DVI?', 4, '[{"text": "Kompatibles Kabel", "correct": false, "because": "Signalübertragung"}, {"text": "Monitor", "correct": false, "because": "Anzeigegerät nötig"}, {"text": "Audiokabel", "correct": true, "because": "Kein Audio"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DVI abwärtskompatibel mit VGA?', 2, '[{"text": "Ja", "correct": true, "because": "Mit DVI-I und Adapter"}, {"text": "Nein", "correct": false, "because": "Kompatibilität möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte nutzen DVI typischerweise?', 4, '[{"text": "PCs", "correct": true, "because": "Videoausgang"}, {"text": "Monitore", "correct": true, "because": "Eingang"}, {"text": "Drucker", "correct": false, "because": "Keine Videoübertragung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DVI nur für alte Geräte ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Noch in Nutzung"}, {"text": "Ja", "correct": false, "because": "Nicht veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei DVI?', 3, '[{"text": "Kabelkompatibilität", "correct": true, "because": "DVI-D, -A, -I"}, {"text": "Kabelfarbe", "correct": false, "because": "Irrelevant"}, {"text": "Audiokanäle", "correct": false, "because": "Kein Audio"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DVI-I unterstützt analog und digital. b) DVI überträgt Audio.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kein Audio"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unterschiede gibt es zu HDMI?', 5, '[{"text": "Kein Audio", "correct": true, "because": "DVI nur Video"}, {"text": "Ältere Technologie", "correct": true, "because": "Vor HDMI"}, {"text": "Höhere Bandbreite", "correct": false, "because": "HDMI moderner"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei DVI unwichtig?', 3, '[{"text": "Signaltyp", "correct": false, "because": "Digital/Analog entscheidend"}, {"text": "Auflösung", "correct": false, "because": "Qualität beeinflusst"}, {"text": "Kabellänge", "correct": true, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt DVI hohe Auflösungen?', 3, '[{"text": "Ja", "correct": true, "because": "Bis 2560x1600"}, {"text": "Nein", "correct": false, "because": "Hohe Auflösungen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DVI mit HDMI kompatibel ist?', 2, '[{"text": "Ja", "correct": true, "because": "Mit Adapter"}, {"text": "Nein", "correct": false, "because": "Adapter möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature macht DVI besonders?', 4, '[{"text": "Duale Signalunterstützung", "correct": true, "because": "DVI-I für analog/digital"}, {"text": "Audiokanäle", "correct": false, "because": "Kein Audio"}, {"text": "Netzwerkfähigkeit", "correct": false, "because": "Nur Video"}]');
